#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// DomainUpDown's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/domain_up_down.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// The selected item (SelectedIndex), or none when the text equals no item; a view onto the selection the text follows. A write selects an item and shows its text, or clears the selection and keeps the text, and raises selected_index_changed. An index past the end throws std::out_of_range.
template <typename Declaring>
struct DomainUpDownSelectedIndexCapability {
    PropertyView<std::optional<std::size_t>, DomainUpDownSelectedIndexCapability<Declaring>> selected_index;

    static void assign(DomainUpDownSelectedIndexCapability& capability, std::optional<std::size_t> incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.selected_index), std::move(incoming));
    }

    static std::optional<std::size_t> read(const DomainUpDownSelectedIndexCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        std::optional<std::size_t> current = control.read_view(capability.selected_index);
        return current;
    }
};

// The field's text (Text); a view onto the editor. A write sets the editor's text and re-matches the selection to it. Allowed on a read-only field: read-only stops typing, not the program.
template <typename Declaring>
struct DomainUpDownTextCapability {
    PropertyView<std::string, DomainUpDownTextCapability<Declaring>> text;

    static void assign(DomainUpDownTextCapability& capability, std::string incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.text), std::move(incoming));
    }

    static std::string read(const DomainUpDownTextCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        std::string current = control.read_view(capability.text);
        return current;
    }
};

// Stepping past either end continues at the other while wrap is on (Wrap).
template <typename Declaring>
struct DomainUpDownWrapCapability {
    PropertyCell<bool, DomainUpDownWrapCapability<Declaring>> wrap{};

    static void assign(DomainUpDownWrapCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.wrap), incoming);
        if (!capability.wrap.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.wrap));
    }
};

// Whether typing is refused (ReadOnly): a typed character then selects the next item that starts with it. A change clears the editor's undo history.
template <typename Declaring>
struct DomainUpDownReadOnlyCapability {
    PropertyCell<bool, DomainUpDownReadOnlyCapability<Declaring>> read_only{};

    static void assign(DomainUpDownReadOnlyCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.read_only), incoming);
        if (!capability.read_only.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.read_only));
    }
};

// Whether the items are kept sorted (Sorted): ASCII case folded, then byte order. Turning it on sorts them and re-matches the selection.
template <typename Declaring>
struct DomainUpDownSortedCapability {
    PropertyCell<bool, DomainUpDownSortedCapability<Declaring>> sorted{};

    static void assign(DomainUpDownSortedCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.sorted), incoming);
        if (!capability.sorted.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.sorted));
    }
};

// The width of the arrow buttons, 12 to 64 (std::out_of_range otherwise).
template <typename Declaring>
struct DomainUpDownButtonWidthCapability {
    PropertyCell<double, DomainUpDownButtonWidthCapability<Declaring>> button_width{18.0};

    static void assign(DomainUpDownButtonWidthCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.button_width), incoming);
        if (!capability.button_width.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.button_width));
    }
};

// Every DomainUpDown capability, in the order the declaring class takes them.
template <typename Declaring>
struct DomainUpDownCapabilities : public DomainUpDownSelectedIndexCapability<Declaring>,
                                  public DomainUpDownTextCapability<Declaring>,
                                  public DomainUpDownWrapCapability<Declaring>,
                                  public DomainUpDownReadOnlyCapability<Declaring>,
                                  public DomainUpDownSortedCapability<Declaring>,
                                  public DomainUpDownButtonWidthCapability<Declaring> {};

} // namespace gui_forms
